glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
attribute vec3 a_position;
attribute vec2 a_uv0;
attribute vec2 a_coord;
attribute vec2 a_offsetDir;
attribute vec2 a_offsetWeight;
varying vec2 v_uv;
varying vec4 v_color;
uniform PointParams {
  vec4 color;
  float progress;
  float row;
  float column;
};
const float SPREAD = 2.0;
const float T1 = 0.378;
const float T2 = 0.675;
float getScale(float t) {
  float s1 = mix(1.0, 2.0, t / T1);
  float s2 = mix(2.0, 1.04, (t - T1) / (T2 - T1));
  float s3 = mix(1.04, 0.0, (t - T2) / (1.0 - T2));
  float w1 = 1.0 - step(T1, t);
  float w2 = step(T1, t) * (1.0 - step(T2, t));
  float w3 = step(T2, t);
  float result = w1 * s1 + w2 * s2 + w3 * s3;
  result = mix(1.0, result, step(0.0, t));
  result = mix(result, 0.0, step(1.0, t));
  return result;
}
float getAlpha(float t) {
  float a1 = mix(0.13, 0.67, t / T1);
  float a2 = mix(0.67, 1.0, (t - T1) / (T2 - T1));
  float w1 = 1.0 - step(T1, t);
  float w2 = step(T1, t);
  float result = w1 * a1 + w2 * a2;
  result = mix(0.13, result, step(0.0, t));
  result = mix(result, 1.0, step(T2, t));
  return result;
}
void main () {
  v_uv = a_uv0;
  vec2 center = vec2((column - 1.0) * 0.5, (row - 1.0) * 0.5);
  float maxRadius = length(center);
  float dist = length(a_coord - center);
  float normalizedDist = maxRadius > 0.0 ? dist / maxRadius : 0.0;
  float t = clamp(progress * SPREAD - normalizedDist, 0.0, 1.0);
  vec3 localPos = a_position;
  float s = getScale(t);
  localPos.xy += a_offsetDir * a_offsetWeight.x * (s - 1.0);
  vec4 worldPos = cc_matWorld * vec4(localPos, 1.0);
  gl_Position = cc_matViewProj * worldPos;
  float a = getAlpha(t);
  v_color = vec4(color.rgb, a);
}

glsl3.frag:
precision highp float;
varying vec2 v_uv;
varying vec4 v_color;
uniform sampler2D mainTexture;
void main () {
  vec4 tex = texture2D(mainTexture, v_uv);
  gl_FragColor = tex * v_color;
}

